use serde_json :: json ; use crate :: { Context , ContextMessage , MessageEntry , ModelId , ToolCallFull , ToolCallId , ToolName , ToolResult , } ; use pretty_assertions :: assert_eq ; use super :: * ; use crate :: { ContextMessage , ModelId , Role , TextMessage } ; impl MessagePattern { # [doc = " Creates a new MessagePattern from the given pattern string."] # [doc = ""] # [doc = " # Arguments"] # [doc = ""] # [doc = " * `pattern` - A string where each character represents a message role:"] # [doc = "   - `'u'` for User"] # [doc = "   - `'a'` for Assistant"] # [doc = "   - `'s'` for System"] # [doc = "   - `'t'` for Assistant with tool call"] # [doc = "   - `'r'` for Tool result"] pub fn new (pattern : impl Into < String >) -> Self { Self { pattern : pattern . into () } } # [doc = " Builds a Context from the pattern."] # [doc = ""] # [doc = " Each message will have content in the format \"Message {index}\" where"] # [doc = " index starts from 1. Tool calls and tool results use predefined test"] # [doc = " data."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics if the pattern contains any character other than 'u', 'a', 's',"] # [doc = " 't', or 'r'."] pub fn build (self) -> Context { let model_id = ModelId :: new ("gpt-4") ; let tool_call = ToolCallFull { name : ToolName :: new ("read") , call_id : Some (ToolCallId :: new ("call_123")) , arguments : json ! ({ "path" : "/test/path" }) . into () , thought_signature : None , } ; let tool_result = ToolResult :: new (ToolName :: new ("read")) . call_id (ToolCallId :: new ("call_123")) . success (json ! ({ "content" : "File content" }) . to_string ()) ; let messages : Vec < MessageEntry > = self . pattern . chars () . enumerate () . map (| (i , c) | { let content = format ! ("Message {}" , i + 1) ; match c { 'u' => ContextMessage :: user (& content , Some (model_id . clone ())) , 'a' => ContextMessage :: assistant (& content , None , None , None) , 's' => ContextMessage :: system (& content) , 't' => ContextMessage :: assistant (& content , None , None , Some (vec ! [tool_call . clone ()]) ,) , 'r' => ContextMessage :: tool_result (tool_result . clone ()) , _ => { panic ! ("Invalid character '{c}' in pattern. Use 'u', 'a', 's', 't', or 'r'") } } }) . map (MessageEntry :: from) . collect () ; Context :: default () . messages (messages) } }